package com.nigson.experience.lead;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import com.nigson.experience.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;

class LeadPersistenceTest {
    private JdbcTemplate jdbc;private PlatformStore store;private LeadService service;private Clock clock;private LeadService.AntiSpamVerifier spam;private LeadService.RateLimiter limiter;
    @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"lead PostgreSQL acceptance uses isolated native owner DB");if(!url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime");jdbc=new JdbcTemplate(ds);clock=Clock.systemUTC();var manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();store=new PlatformStore(jdbc,manager,clock,metrics);spam=new LocalLeadMocks.AntiSpam(Base64.getEncoder().encodeToString(new byte[32]));limiter=new LocalLeadMocks.RateLimit(1000,clock);service=new LeadService(jdbc,store,new AuditWriter(jdbc,clock,metrics),metrics,manager,clock,spam,limiter,"synthetic-sales-triage","https://admin.synthetic.invalid");}
    private LeadValues.Enquiry request(String subject,String token){return new LeadValues.Enquiry("COMPLAINT","Synthetic User","user@example.invalid","+2348031234567",subject,"private complaint body that must not enter EVT-016",token);}
    private LeadValues.Created create(String subject,String key){String token=((LocalLeadMocks.AntiSpam)spam).sign("syntheticnonce123456",key);return service.create(request(subject,token),key,"127.0.0.1",UUID.randomUUID());}
    private PrivateWorkload.Proof proof(String api,UUID party,String role){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow();var actor=party==null?null:new ActorAssertion.Actor(party,"https://identity.synthetic.invalid","lead-staff",null,Set.of(role),Set.of(route.scope()),null);return new PrivateWorkload.Proof(route.client(),"synthetic-workload",route,actor);}

    @Test void intakeReplaysOnceAndOutboxFailureKeepsTheCommittedLeadForNotificationRetry(){String key=UUID.randomUUID().toString();var lead=create("Synthetic complaint",key);assertThat(lead.state()).isEqualTo("NEW");assertThat(create("Synthetic complaint",key)).isEqualTo(lead);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE id=?",Long.class,lead.id())).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead_activity WHERE lead_id=? AND activity_type='RECEIVED'",Long.class,lead.id())).isEqualTo(1);String payload=jdbc.queryForObject("SELECT payload::text FROM experience.outbox_event WHERE aggregate_id=? AND event_type='lead.created.v1'",String.class,lead.id());assertThat(EventCodec.decode(payload).path("payload").path("recipient_group").asString()).isEqualTo("synthetic-sales-triage");assertThat(payload).doesNotContain("user@example.invalid","private complaint body","Synthetic complaint");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.audit_record WHERE resource_id=? AND action='LEAD_CREATE'",Long.class,lead.id())).isEqualTo(1);
        var claim=store.claim(100,Duration.ofSeconds(15)).stream().filter(c->EventCodec.decode(c.body()).path("aggregate_id").asString().equals(lead.id().toString())).findFirst().orElseThrow();store.failed(claim,5);UUID event=UUID.fromString(EventCodec.decode(claim.body()).path("event_id").asString());assertThat(jdbc.queryForObject("SELECT state FROM experience.outbox_event WHERE event_id=?",String.class,event)).isEqualTo("PENDING");assertThat(create("Synthetic complaint",key)).isEqualTo(lead);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE id=?",Long.class,lead.id())).isEqualTo(1L);}
    @Test void assignmentVersionOwnershipAndNotificationContextAreOwnerScoped(){String key=UUID.randomUUID().toString();var created=create("Staff triage request",key);UUID staff=UUID.randomUUID();var listed=service.list(proof("API-089",staff,"SALES"),null,"NEW",null,null,0,20,"createdAt,desc");assertThat(listed.items()).extracting(LeadValues.Lead::id).contains(created.id());var current=service.detail(proof("API-090",staff,"SALES"),created.id());var patch=new LeadValues.Patch("ASSIGNED",true,staff,true,"HIGH",true,null,false,"Claimed for follow-up");var changed=service.update(proof("API-091",staff,"SALES"),created.id(),patch,current.version(),UUID.randomUUID().toString(),UUID.randomUUID());assertThat(changed.assignedTo()).isEqualTo(staff);assertThat(changed.version()).isEqualTo(current.version()+1);assertThatThrownBy(()->service.detail(proof("API-090",UUID.randomUUID(),"SALES"),created.id())).isInstanceOf(Problem.Failure.class).hasMessage("NOT_FOUND");assertThatThrownBy(()->service.update(proof("API-091",staff,"SALES"),created.id(),patch,current.version(),UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).hasMessage("VERSION_MISMATCH");var privateContext=service.notificationContext(proof("API-129",null,null),created.id());assertThat(privateContext.recipientGroup()).isEqualTo("synthetic-sales-triage");assertThat(privateContext.adminLink()).isEqualTo("https://admin.synthetic.invalid/staff/leads/"+created.id());assertThat(privateContext.subject()).isEqualTo("Staff triage request");}
    @Test void idempotencyConflictAndAuditFailureRollbackAllLocalLeadEffects(){String key=UUID.randomUUID().toString();var first=create("Original subject",key);String altered=((LocalLeadMocks.AntiSpam)spam).sign("syntheticnonce123456",key);assertThatThrownBy(()->service.create(request("Changed subject",altered),key,"127.0.0.1",UUID.randomUUID())).isInstanceOf(PlatformStore.Conflict.class).hasMessage("IDEMPOTENCY_HASH_MISMATCH");
        long eventCount=jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE event_type='lead.created.v1'",Long.class);long activityCount=jdbc.queryForObject("SELECT count(*) FROM experience.lead_activity WHERE note='Public enquiry received'",Long.class);var manager=new DataSourceTransactionManager(jdbc.getDataSource());var failing=mock(AuditWriter.class);doThrow(new IllegalStateException("synthetic audit failure")).when(failing).append(anyString(),any(),any(),any(),any(),any(),any(),any(),any(),any());var failedService=new LeadService(jdbc,store,failing,new SimpleMeterRegistry(),manager,clock,spam,limiter,"synthetic-sales-triage","https://admin.synthetic.invalid");String failedKey=UUID.randomUUID().toString();String token=((LocalLeadMocks.AntiSpam)spam).sign("syntheticnonce123456",failedKey);assertThatThrownBy(()->failedService.create(request("Rollback subject",token),failedKey,"127.0.0.1",UUID.randomUUID())).isInstanceOf(IllegalStateException.class);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE subject='Rollback subject'",Long.class)).isZero();assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE event_type='lead.created.v1'",Long.class)).isEqualTo(eventCount);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead_activity WHERE note='Public enquiry received'",Long.class)).isEqualTo(activityCount);}
    @Test void concurrentSameKeyCreatesOneLeadAndOneEvent()throws Exception{String key=UUID.randomUUID().toString(),token=((LocalLeadMocks.AntiSpam)spam).sign("syntheticnonce123456",key);var req=request("Race subject",token);var gate=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(8);try{var futures=new ArrayList<Future<?>>();for(int i=0;i<8;i++)futures.add(pool.submit(()->{gate.await();try{service.create(req,key,"127.0.0.1",UUID.randomUUID());}catch(PlatformStore.Conflict expected){}return null;}));gate.countDown();for(var f:futures)f.get(10,TimeUnit.SECONDS);}finally{pool.shutdownNow();}var result=service.create(req,key,"127.0.0.1",UUID.randomUUID());assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.lead WHERE id=?",Long.class,result.id())).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='lead.created.v1'",Long.class,result.id())).isEqualTo(1);}
}
